# ClockSkewCorrector — Timezone & Monotonicity Validation
# ---------------------------------------------------------------------------

class TestClockSkewCorrector:
    """Validates timezone mixing, DST transitions, and monotonic ordering."""

    @pytest.fixture
    def corrector(self) -> ClockSkewCorrector:
        return ClockSkewCorrector(skew_threshold_seconds=30)

    def test_naive_and_aware_timestamps_raise(self, corrector: ClockSkewCorrector):
        """Mixing naive and timezone-aware timestamps is a data integrity error."""
        mixed_index = pd.DatetimeIndex(
            [
                pd.Timestamp("2024-01-01 00:00:00"),
                pd.Timestamp("2024-01-01 00:01:00", tz="UTC"),
            ]
        )
        with pytest.raises(ValueError, match="timezone"):
            corrector.transform(mixed_index)

    def test_dst_transition_handled(self, corrector: ClockSkewCorrector):
        """DST spring-forward should not produce negative or zero diffs."""
        dst_index = pd.date_range(
            "2024-03-10 01:30:00",
            periods=5,
            freq="30min",
            tz="America/New_York",
        )
        corrected = corrector.transform(dst_index)
        diffs = corrected.to_series().diff().dropna()
        assert (diffs > pd.Timedelta(0)).all(), "DST transition produced non-monotonic diffs"

    def test_out_of_order_timestamps_sorted(self, corrector: ClockSkewCorrector):
        """Chronologically shuffled input must be re-ordered."""
        shuffled = pd.DatetimeIndex(
            [
                pd.Timestamp("2024-01-01 00:05:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:00:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:02:00", tz="UTC"),
            ]
        )
        corrected = corrector.transform(shuffled)
        assert corrected.is_monotonic_increasing

    def test_extreme_skew_beyond_threshold_raises(self, corrector: ClockSkewCorrector):
        """A timestamp jump exceeding the skew threshold must raise."""
        skewed = pd.DatetimeIndex(
            [
                pd.Timestamp("2024-01-01 00:00:00", tz="UTC"),
                pd.Timestamp("2024-01-02 00:00:00", tz="UTC"),  # 24h jump
            ]
        )
        with pytest.raises(ValueError, match="skew"):
            corrector.transform(skewed)

    def test_duplicate_timestamps_preserved(self, corrector: ClockSkewCorrector):
        """Duplicate timestamps are valid and must not be dropped."""
        dup_index = pd.DatetimeIndex(
            [
                pd.Timestamp("2024-01-01 00:00:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:00:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:01:00", tz="UTC"),
            ]
        )
        corrected = corrector.transform(dup_index)
        assert len(corrected) == 3
        assert corrected.duplicated().sum() == 1

    @given(
        st.lists(
            st.datetimes(
                min_value=pd.Timestamp("2020-01-01"),
                max_value=pd.Timestamp("2025-12-31"),
                timezones=st.just("UTC"),
            ),
            min_size=1,
            max_size=50,
        )
    )
    @settings(max_examples=50, deadline=None)
    def test_property_monotonic_after_transform(
        self, corrector: ClockSkewCorrector, timestamps: list
    ):
        """Property: output is always monotonically increasing."""
        index = pd.DatetimeIndex(timestamps)
        # Filter out extreme skew to avoid expected raises
        if len(index) > 1:
            diffs = index.to_series().diff().dropna()
            if diffs.max() > pd.Timedelta(seconds=30):
                return  # skip extreme cases
        corrected = corrector.transform(index)
        assert corrected.is_monotonic_increasing


