class TestMissingDataImputer:
    """Validates NaN injection, all-NaN columns, and dtype preservation."""

    @pytest.fixture
    def imputer(self) -> MissingDataImputer:
        return MissingDataImputer(strategy="linear")

    def test_nan_injection_fills_values(self, imputer: MissingDataImputer, sample_df: pd.DataFrame):
        """Linear interpolation should fill interior NaNs."""
        df_with_nan = sample_df.copy()
        df_with_nan.iloc[10:15, 0] = np.nan
        result = imputer.transform(df_with_nan)
        assert not result["sensor_a"].iloc[10:15].isna().any()
        # Interpolated values should be finite
        assert np.isfinite(result["sensor_a"].iloc[10:15]).all()

    def test_all_nan_column_raises(self, imputer: MissingDataImputer, sample_df: pd.DataFrame):
        """A column with 100% NaN cannot be imputed and must raise."""
        df_all_nan = sample_df.copy()
        df_all_nan["sensor_b"] = np.nan
        with pytest.raises(ValueError, match="all-NaN"):
            imputer.transform(df_all_nan)

    def test_dtype_preserved_for_int_columns(self, imputer: MissingDataImputer):
        """Integer columns with NaN become float, but non-NaN ints stay int."""
        df = pd.DataFrame({"int_col": [1, 2, np.nan, 4]})
        result = imputer.transform(df)
        assert result["int_col"].dtype == np.float64  # NaN forces float
        assert result["int_col"].iloc[0] == 1.0

    def test_no_nan_input_unchanged(self, imputer: MissingDataImputer, sample_df: pd.DataFrame):
        """Clean data should pass through without modification."""
        result = imputer.transform(sample_df)
        pd.testing.assert_frame_equal(result, sample_df)

    def test_leading_trailing_nan_handled(self, imputer: MissingDataImputer):
        """Edge NaNs (first/last rows) should be filled via nearest or remain NaN."""
        df = pd.DataFrame({"col": [np.nan, 1.0, 2.0, np.nan]})
        result = imputer.transform(df)
        # Linear interpolation leaves edge NaNs; strategy should handle them
        assert result["col"].iloc[1] == 1.0
        assert result["col"].iloc[2] == 2.0

    @given(
        st.data_frames(
            [
                st.column("a", elements=st.floats(allow_nan=False, allow_infinity=False)),
                st.column("b", elements=st.floats(allow_nan=False, allow_infinity=False)),
            ],
            index=st.datetimes(min_value=pd.Timestamp("2024-01-01"), max_value=pd.Timestamp("2024-12-31")),
        )
    )
    @settings(max_examples=30, deadline=None)
    def test_property_no_new_nan_after_imputation(
        self, imputer: MissingDataImputer, df: pd.DataFrame
    ):
        """Property: imputation never introduces new NaNs in interior."""
        if df.empty or len(df) < 3:
            return
        # Inject interior NaNs
        df_with_nan = df.copy()
        for col in df_with_nan.columns:
            interior_idx = df_with_nan.index[1:-1]
            if len(interior_idx) > 0:
                mask = np.random.default_rng(0).choice(
                    [True, False], size=len(interior_idx), p=[0.2, 0.8]
                )
                df_with_nan.loc[interior_idx[mask], col] = np.nan
        result = imputer.transform(df_with_nan)
        # No new NaNs beyond original edges
        for col in result.columns:
            original_nan = df_with_nan[col].isna()
            result_nan = result[col].isna()
            # Any NaN in result must have been NaN in input
            assert not (result_nan & ~original_nan).any()


