class TestTemporalAlignment:
    """Validates resampling, irregular intervals, and duplicate timestamps."""

    @pytest.fixture
    def aligner(self) -> TemporalAlignment:
        return TemporalAlignment(freq="1min")

    def test_regular_resampling(self, aligner: TemporalAlignment, sample_df: pd.DataFrame):
        """Regular 1-min data should resample without loss."""
        result = aligner.transform(sample_df)
        assert len(result) == len(sample_df)
        assert result.index.freq is not None

    def test_irregular_intervals_resampled(self, aligner: TemporalAlignment):
        """Irregular timestamps should be aligned to the target frequency."""
        irregular_idx = pd.DatetimeIndex(
            [
                pd.Timestamp("2024-01-01 00:00:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:00:30", tz="UTC"),
                pd.Timestamp("2024-01-01 00:02:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:03:30", tz="UTC"),
            ]
        )
        df = pd.DataFrame({"value": [1.0, 2.0, 3.0, 4.0]}, index=irregular_idx)
        result = aligner.transform(df)
        # Should produce 4 one-minute buckets (00:00, 00:01, 00:02, 00:03)
        assert len(result) == 4
        assert result.index[0] == pd.Timestamp("2024-01-01 00:00:00", tz="UTC")

    def test_duplicate_timestamps_aggregated(self, aligner: TemporalAlignment):
        """Duplicate timestamps should be aggregated (mean by default)."""
        dup_idx = pd.DatetimeIndex(
            [
                pd.Timestamp("2024-01-01 00:00:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:00:00", tz="UTC"),
                pd.Timestamp("2024-01-01 00:01:00", tz="UTC"),
            ]
        )
        df = pd.DataFrame({"value": [1.0, 3.0, 2.0]}, index=dup_idx)
        result = aligner.transform(df)
        # First bucket should be mean(1,3) = 2.0
        assert result["value"].iloc[0] == pytest.approx(2.0)

    def test_empty_frame_returns_empty(self, aligner: TemporalAlignment):
        """Empty input should produce empty output without error."""
        empty_df = pd.DataFrame(columns=["value"])
        result = aligner.transform(empty_df)
        assert result.empty

    def test_single_row_passthrough(self, aligner: TemporalAlignment):
        """A single row should not crash and should retain its value."""
        single_idx = pd.DatetimeIndex([pd.Timestamp("2024-01-01 00:00:00", tz="UTC")])
        df = pd.DataFrame({"value": [42.0]}, index=single_idx)
        result = aligner.transform(df)
        assert len(result) == 1
        assert result["value"].iloc[0] == 42.0

    @given(
        st.lists(
            st.datetimes(
                min_value=pd.Timestamp("2024-01-01"),
                max_value=pd.Timestamp("2024-01-02"),
                timezones=st.just("UTC"),
            ),
            min_size=1,
            max_size=100,
        )
    )
    @settings(max_examples=30, deadline=None)
    def test_property_output_index_monotonic(
        self, aligner: TemporalAlignment, timestamps: list
    ):
        """Property: output index is always monotonically increasing."""
        df = pd.DataFrame(
            {"value": np.random.default_rng(1).normal(size=len(timestamps))},
            index=pd.DatetimeIndex(timestamps),
        )
        result = aligner.transform(df)
        assert result.index.is_monotonic_increasing


