class TestFeaturePipeline:
    """Validates full pipeline orchestration, error propagation, and mocking."""

    @pytest.fixture
    def pipeline(self, config: FeaturePipelineConfig) -> FeaturePipeline:
        return FeaturePipeline(config=config)

    def test_full_pipeline_runs(self, pipeline: FeaturePipeline, sample_df: pd.DataFrame):
        """End-to-end execution should produce a valid output DataFrame."""
        result = pipeline.run(sample_df)
        assert isinstance(result, pd.DataFrame)
        assert not result.empty
        assert result.index.is_monotonic_increasing

    def test_pipeline_preserves_columns(self, pipeline: FeaturePipeline, sample_df: pd.DataFrame):
        """All input columns should survive the pipeline."""
        result = pipeline.run(sample_df)
        assert set(result.columns) == set(sample_df.columns)

    def test_pipeline_handles_nan_input(self, pipeline: FeaturePipeline, sample_df: pd.DataFrame):
        """Pipeline should gracefully handle NaN-contaminated input."""
        df_with_nan = sample_df.copy()
        df_with_nan.iloc[20:25, 1] = np.nan
        result = pipeline.run(df_with_nan)
        assert not result["sensor_b"].iloc[20:25].isna().any()

    def test_pipeline_raises_on_all_nan_column(
        self, pipeline: FeaturePipeline, sample_df: pd.DataFrame
    ):
        """All-NaN columns should propagate an error from the imputer."""
        df_all_nan = sample_df.copy()
        df_all_nan["sensor_c"] = np.nan
        with pytest.raises(ValueError, match="all-NaN"):
            pipeline.run(df_all_nan)

    def test_pipeline_mock_isolation(self, config: FeaturePipelineConfig):
        """I/O-bound methods should be mockable for isolated testing."""
        with patch(
            "feature_pipeline.pipeline.ClockSkewCorrector.transform",
            return_value=pd.DatetimeIndex(
                [pd.Timestamp("2024-01-01 00:00:00", tz="UTC")] * 10
            ),
        ) as mock_skew:
            pipeline = FeaturePipeline(config=config)
            df = pd.DataFrame(
                {"value": np.arange(10.0)},
                index=pd.date_range("2024-01-01", periods=10, freq="min", tz="UTC"),
            )
            result = pipeline.run(df)
            mock_skew.assert_called_once()
            assert len(result) == 10

    def test_pipeline_error_propagation(self, pipeline: FeaturePipeline):
        """Errors from sub-components should propagate with context."""
        bad_df = pd.DataFrame({"value": [1.0, 2.0]})  # no datetime index
        with pytest.raises((ValueError, TypeError)):
            pipeline.run(bad_df)

    def test_pipeline_empty_input(self, pipeline: FeaturePipeline):
        """Empty DataFrame should raise a clear error."""
        empty_df = pd.DataFrame()
        with pytest.raises(ValueError, match="empty"):
            pipeline.run(empty_df)

    def test_pipeline_logs_execution(self, pipeline: FeaturePipeline, sample_df: pd.DataFrame, caplog):
        """Pipeline should emit structured log entries during execution."""
        import logging
        with caplog.at_level(logging.INFO, logger="feature_pipeline"):
            pipeline.run(sample_df)
        assert any("pipeline" in rec.message.lower() for rec in caplog.records)


