class TestChaosEdgeCases:
    """Extreme and pathological inputs that should not crash the system."""

    def test_extreme_large_dataframe(self, rng: np.random.Generator):
        """100k rows should process without memory explosion or crash."""
        idx = pd.date_range("2020-01-01", periods=100_000, freq="s", tz="UTC")
        df = pd.DataFrame(
            {"value": rng.normal(size=100_000)},
            index=idx,
        )
        pipeline = FeaturePipeline(
            config=FeaturePipelineConfig(
                skew_threshold_seconds=60,
                impute_strategy="linear",
                resample_freq="1min",
                rolling_window=10,
                rolling_min_periods=5,
            )
        )
        result = pipeline.run(df)
        assert len(result) > 0

    def test_all_duplicate_timestamps(self):
        """All timestamps identical should not crash."""
        idx = pd.DatetimeIndex([pd.Timestamp("2024-01-01 00:00:00", tz="UTC")] * 50)
        df = pd.DataFrame({"value": np.arange(50.0)}, index=idx)
        pipeline = FeaturePipeline(
            config=FeaturePipelineConfig(
                skew_threshold_seconds=60,
                impute_strategy="linear",
                resample_freq="1min",
                rolling_window=5,
                rolling_min_periods=3,
            )
        )
        result = pipeline.run(df)
        assert len(result) == 1  # all collapsed to one bucket

    def test_negative_values_and_zeros(self, rng: np.random.Generator):
        """Negative and zero values should not break rolling or imputation."""
        idx = pd.date_range("2024-01-01", periods=50, freq="min", tz="UTC")
        df = pd.DataFrame(
            {
                "neg": rng.normal(-100, 10, 50),
                "zero": np.zeros(50),
                "mixed": rng.normal(0, 1, 50),
            },
            index=idx,
        )
        pipeline = FeaturePipeline(
            config=FeaturePipelineConfig(
                skew_threshold_seconds=60,
                impute_strategy="linear",
                resample_freq="1min",
                rolling_window=5,
                rolling_min_periods=3,
            )
        )
        result = pipeline.run(df)
        assert np.isfinite(result.values).all()

    def test_mixed_dtypes(self):
        """Mixed numeric and categorical columns should be handled or raise clearly."""
        idx = pd.date_range("2024-01-01", periods=10, freq="min", tz="UTC")
        df = pd.DataFrame(
            {
                "numeric": np.arange(10.0),
                "category": ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"],
            },
            index=idx,
        )
        pipeline = FeaturePipeline(
            config=FeaturePipelineConfig(
                skew_threshold_seconds=60,
                impute_strategy="linear",
                resample_freq="1min",
                rolling_window=3,
                rolling_min_periods=2,
            )
        )
        # Should either process numeric only or raise a clear error
        try:
            result = pipeline.run(df)
            assert "numeric" in result.columns
        except (ValueError, TypeError) as e:
            assert "categorical" in str(e).lower() or "non-numeric" in str(e).lower()